const app=document.querySelector('#app');
const state={data:null,locale:localStorage.getItem('dracula.language')||'ro',cart:{items:[]},profile:null,favorites:[],filter:'all',search:'',auth:'login',order:null,checkoutKey:null};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>esc(state.data?.ui[k]||k);
const money=n=>new Intl.NumberFormat(state.locale,{style:'currency',currency:state.data.currency}).format(Number(n)||0);
const href=path=>`/${state.locale}${path}`;
const link=(path,label,cls='')=>`<a class="${cls}" href="${href(path)}" data-link>${label}</a>`;
const icon=name=>`<svg class="sigil" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.25" aria-hidden="true">${({bag:'<path d="M7 10h18l2 17H5L7 10ZM11 11V8a5 5 0 0 1 10 0v3M11 17l5 7 5-7M16 14v10"/>',favorite:'<path d="M16 3 27 13 16 29 5 13 16 3ZM5 13h22M11 8l5 16 5-16"/>',account:'<path d="M16 3 28 10v12l-12 7L4 22V10L16 3Z"/><circle cx="16" cy="12" r="4"/><path d="M9 24v-3a7 7 0 0 1 14 0v3"/>',buy:'<path d="M3 16h24M19 7l9 9-9 9M9 10l5 6-5 6"/>',close:'<path d="m8 8 16 16M24 8 8 24"/>'})[name]}</svg>`;
function route(){const parts=location.pathname.split('/').filter(Boolean);if(state.data?.languages.includes(parts[0]))parts.shift();return '/'+parts.join('/');}
async function api(path,method='GET',body,extra={}){const csrf=decodeURIComponent(document.cookie.split('; ').find(c=>c.startsWith('dracula_csrf='))?.split('=').slice(1).join('=')||'');const r=await fetch(path+(path.includes('?')?'&':'?')+'lang='+state.locale,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...extra},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(data.error||data.code||'general');e.status=r.status;throw e;}return data;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4500);}
function errorMessage(e){return state.data?.ui['error.'+e.message]||state.data?.ui['error.general']||e.message;}
async function refresh(){const results=await Promise.allSettled([api('/api/cart'),api('/api/account/profile'),api('/api/account/favorites')]);if(results[0].status==='fulfilled')state.cart=results[0].value;state.profile=results[1].status==='fulfilled'?results[1].value.profile:null;state.favorites=results[2].status==='fulfilled'?results[2].value.items:[];}
function saved(p){return state.favorites.some(f=>f.product_id===p.id||f.id===p.external_id||f.id===p.id);}
function image(p,cls='',lazy=true){return `<img class="${cls}" src="${esc(p.image)}" alt="${esc(p.name)}" ${lazy?'loading="lazy"':''}>`;}
function favourite(p){return `<button class="icon-button ${saved(p)?'selected':''}" data-action="favorite" data-id="${p.id}" aria-pressed="${saved(p)}" aria-label="${t(saved(p)?'product.unfavorite':'product.favorite')}" title="${t('nav.favorites')}">${icon('favorite')}</button>`;}
function header(){return `<a class="skip-link" href="#main">${t('access.skip')}</a>${state.data.demo?`<div class="preview-label">${t('demo.label')}</div>`:''}<header class="header"><a href="${href('/')}" data-link class="logo"><img src="${esc(state.data.brand.logo_url)}" alt="${esc(state.data.brand.name)}"></a><nav aria-label="${t('access.navigation')}">${link('/collection',t('nav.collection'))}${link('/#signature',t('nav.story'))}${link('/#universe',t('nav.universe'))}</nav><div class="header-tools"><label class="language"><span class="sr-only">${t('nav.language')}</span><select id="language">${state.data.languages.map(l=>`<option ${l===state.locale?'selected':''} value="${l}">${l.toUpperCase()}</option>`).join('')}</select></label>${link('/account',icon('account')+`<span class="sr-only">${t('nav.account')}</span>`,'icon-button')}${link('/favorites',icon('favorite')+`<span class="sr-only">${t('nav.favorites')}</span>`,'icon-button')}${link('/bag',icon('bag')+`<span class="bag-count">${state.cart.items_count||0}</span><span class="sr-only">${t('nav.bag')}</span>`,'icon-button')}</div></header>`;}
function footer(){const group=(key,slugs)=>`<div><h3>${t(key)}</h3>${slugs.map(slug=>{const p=state.data.pages.find(p=>p.slug===slug);return p?link('/pages/'+slug,esc(p.title)):'';}).join('')}</div>`;return `<footer class="shop-footer"><div class="footer-brand"><img src="${esc(state.data.brand.logo_url)}" alt="${esc(state.data.brand.name)}"><p>${esc(state.data.legal.company_name)}<br>${esc(state.data.legal.address)}</p></div>${group('footer.client',['contact','shipping','payments','returns','withdrawal','faq'])}${group('footer.house',['about','legal-notice','accessibility'])}${group('footer.legal',['terms','privacy','cookies','data-deletion','complaints'])}<div class="footer-bottom"><span>Â© ${new Date().getFullYear()} ${esc(state.data.brand.name)}. ${t('footer.rights')}</span><a href="/admin/">${t('footer.admin')}</a></div></footer>`;}
function card(p,index=0){return `<article class="product ${index>2?'product-wide':''}"><div class="card-image">${link('/product/'+p.external_id,image(p)+'<span class="view-label">'+t('product.discover')+' â†—</span>','product-image')}${favourite(p)}</div><div class="product-meta"><p>${esc(p.sku)}</p><h3>${link('/product/'+p.external_id,esc(p.name))}</h3><div class="price-row"><span>${money(p.price)} ${state.data.demo?`<small>${t('demo.price')}</small>`:''}</span><button class="icon-button" data-action="add" data-id="${p.id}" ${p.available<1?'disabled':''} aria-label="${t('product.add')}" title="${t('product.add')}">${icon('bag')}</button></div></div></article>`;}
function collection(){const products=state.data.products.filter(p=>(state.filter==='all'||p.category===state.filter||p.categories?.includes(state.filter))&&(`${p.name} ${p.description}`).toLowerCase().includes(state.search.toLowerCase()));return `<div class="collection-tools"><div class="filters">${['all',...state.data.categories.map(c=>c.code)].map(f=>`<button class="${state.filter===f?'active':''}" data-action="filter" data-filter="${f}">${f==='all'?t('collection.all'):esc(state.data.categories.find(c=>c.code===f)?.name)}</button>`).join('')}</div><label class="search-label"><span class="sr-only">${t('collection.search')}</span><input id="search" type="search" value="${esc(state.search)}" placeholder="${t('collection.search')}"></label></div><div class="product-grid">${products.map(card).join('')||`<p>${t('collection.noresults')}</p>`}</div>`;}
function home(){const d=state.data;return `<section class="hero"><div class="hero-copy"><p class="eyebrow">${t('hero.eyebrow')}</p><h1>${t('hero.title')}<br><em>${t('hero.emphasis')}</em></h1><p class="hero-description">${t('hero.description')}</p>${link('/collection',t('hero.cta')+' <span>â†—</span>','button-outline')}<p class="hero-motto">${t('hero.motto')}</p></div><div class="hero-photo"><img src="${esc(d.images.hero)}" alt="${t('hero.eyebrow')}" fetchpriority="high"></div><div class="hero-caption"><span>${t('hero.caption')}</span><a href="#collection">${t('hero.scroll')} â†“</a></div></section><section class="section" id="collection"><div class="section-heading"><div><p class="eyebrow">${t('collection.eyebrow')}</p><h2>${t('collection.title')}<br><em>${t('collection.emphasis')}</em></h2></div><p class="intro">${t('collection.description')}</p></div>${collection()}</section><section class="section signature" id="signature"><div class="signature-image"><img src="${esc(d.images.collection)}" loading="lazy" alt="${t('signature.title')}"></div><div class="signature-copy"><p class="eyebrow">${t('signature.eyebrow')}</p><h2>${t('signature.title')}<br><em>${t('signature.emphasis')}</em></h2><p class="intro">${t('signature.body')}</p><p class="intro">${t('signature.more')}</p>${link('/pages/about',t('nav.story')+' â†—','text-link')}</div></section><section class="section universe" id="universe"><div class="universe-copy"><p class="eyebrow">${t('universe.eyebrow')}</p><h2>${t('universe.title')}<br><em>${t('universe.emphasis')}</em></h2><p class="intro">${t('universe.body')}</p><p class="universe-manifesto">${t('universe.motto')}</p></div><div class="universe-photo"><img src="${esc(d.images.scarf)}" loading="lazy" alt="${t('universe.eyebrow')}"></div></section>`;}
function product(p){if(!p)return empty('error.not_found');return `<section class="page product-detail"><div class="detail-photo"><button data-action="image" data-id="${p.id}" aria-label="${t('product.fullimage')}">${image(p,'',false)}</button></div><div class="detail-copy"><p class="eyebrow">${t('collection.eyebrow')}</p><h1>${esc(p.name)}</h1><p class="intro">${esc(p.description)}</p><div class="detail-price">${money(p.price)} ${state.data.demo?`<small>${t('demo.price')}</small>`:''}</div><p class="stock">${t(p.available>0?'product.available':'product.unavailable')}</p><div class="purchase-row"><label>${t('product.quantity')}<input type="number" id="quantity" min="1" max="${p.available}" value="1"></label>${favourite(p)}</div><button class="button-primary" data-action="buy" data-id="${p.id}" ${p.available<1?'disabled':''}>${icon('buy')}${t('product.buy')}</button><button class="button-outline full" data-action="add" data-id="${p.id}" ${p.available<1?'disabled':''}>${icon('bag')}${t('product.add')}</button><p class="fineprint">${t('product.price_note')}</p><details open><summary>${t('product.details')}</summary><div>${rich(p.details)}</div><p>${t('product.code')}: ${esc(p.sku)}</p></details><details><summary>${t('product.care')}</summary><p>${t('product.caretext')}</p></details><details><summary>${t('product.delivery')}</summary><p>${t('product.deliverytext')}</p>${link('/pages/returns',t('product.delivery'))}</details></div></section><section class="section"><h2>${t('product.related')}</h2><div class="product-grid related">${state.data.products.filter(x=>x.id!==p.id).slice(0,3).map(card).join('')}</div></section>`;}
function empty(key){return `<div class="empty"><span class="empty-sigil">${icon('favorite')}</span><h2>${t(key)}</h2>${link('/collection',t('action.continue'),'button-outline')}</div>`;}
function bagRows(edit=true){return state.cart.items.map(i=>`<article class="bag-row">${link('/product/'+i.id,`<img src="${esc(i.image)}" alt="${esc(i.name)}">`)}<div><h3>${link('/product/'+i.id,esc(i.name))}</h3><p>${money(i.unit_price_gross_ron)}</p>${edit?`<label>${t('product.quantity')} <input aria-label="${t('product.quantity')}" type="number" value="${i.qty}" min="1" max="${i.available}" data-qty="${i.product_id}"></label><button class="quiet" data-action="remove" data-id="${i.product_id}">${t('action.remove')}</button>`:`<span>Ã— ${i.qty}</span>`}</div><strong>${money(i.line_total_gross_ron)}</strong></article>`).join('');}
function bag(){return `<section class="page"><p class="eyebrow">${t('nav.bag')}</p><h1>${t('bag.title')}</h1>${!state.cart.items.length?empty('bag.empty'):`<div class="checkout-grid"><div>${bagRows()}</div><aside class="order-summary"><h2>${t('bag.subtotal')}</h2><p class="total">${money(state.cart.products_gross_ron)}</p><p class="fineprint">${t('product.price_note')}</p>${state.data.demo?`<p class="notice">${t('checkout.demo_notice')}</p>`:''}${link('/checkout',t('bag.checkout')+' â†—','button-primary')}</aside></div>`}</section>`;}
function field(name,key,type='text',value='',required=true,extra=''){return `<label class="field">${t(key)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;}
function password(name,key){return field(name,key,'password','',true,'minlength="10" maxlength="200" autocomplete="new-password"');}
function formError(){return '<p class="form-error" role="alert"></p>';}
function auth(){const mode=state.auth;return `<section class="page auth-page"><div><p class="eyebrow">${t('hero.eyebrow')}</p><h1>${t('account.title')}</h1><p class="intro">${t('account.intro')}</p><span class="large-sigil">${icon('account')}</span></div><div class="form-panel"><div class="auth-tabs">${['login','register'].map(m=>`<button class="${m===mode?'active':''}" data-action="auth" data-mode="${m}">${t('auth.'+m)}</button>`).join('')}</div><form data-form="${mode}">${mode==='register'?field('full_name','auth.name')+field('phone','auth.phone','tel','',false):''}${field('email','auth.email','email','',true,'autocomplete="email"')}${mode!=='forgot'?field('password','auth.password','password','',true,`minlength="10" autocomplete="${mode==='login'?'current-password':'new-password'}"`):''}${mode==='register'?password('password_confirm','auth.confirm')+`<p class="fineprint">${t('auth.password_hint')}</p><label class="check"><input name="accept_terms" type="checkbox" required>${t('auth.terms')} ${link('/pages/terms',state.data.pages.find(p=>p.slug==='terms').title)}</label>`:''}${formError()}<button class="button-primary" type="submit">${t(mode==='forgot'?'auth.reset_action':'auth.'+mode+'_action')}</button></form>${mode==='login'?`<button class="quiet" data-action="auth" data-mode="forgot">${t('auth.forgot')}</button>`:''}<p class="fineprint">${link('/pages/privacy',t('auth.privacy'))}</p></div></section>`;}
async function account(){if(!state.profile)return auth();const p=state.profile;const orders=await api('/api/account/orders');return `<section class="page"><div class="page-heading"><div><p class="eyebrow">${t('account.title')}</p><h1>${esc(p.full_name||p.name||p.email)}</h1></div><button class="quiet" data-action="logout">${t('account.logout')}</button></div><div class="account-grid"><div><h2>${t('account.orders')}</h2>${orders.orders.length?orders.orders.map(o=>`<article class="order-card"><div><strong>${esc(o.order_number||o.id)}</strong><span>${t('status.'+o.status)}</span></div><p>${esc(o.created_at_display||o.created_at?.slice(0,10))}</p><p>${money(o.total_gross_ron||o.total_ron||o.total)}</p><button class="quiet" data-action="order" data-number="${esc(o.order_number||o.id)}">${t('action.view')}</button></article>`).join(''):`<p class="intro">${t('account.noorders')}</p>`}</div><div class="form-panel"><h2>${t('account.profile')}</h2><form data-form="profile">${field('full_name','auth.name','text',p.full_name||p.name)}${field('phone','auth.phone','tel',p.phone,false)}${formError()}<button class="button-outline">${t('action.save')}</button></form><h2>${t('account.password')}</h2><form data-form="password">${field('current_password','auth.currentpassword','password')}${password('new_password','auth.newpassword')}${password('password_confirm','auth.confirm')}${formError()}<button class="button-outline">${t('action.save')}</button></form></div></div></section>`;}
function checkout(){if(!state.profile)return auth();if(!state.cart.items.length)return bag();state.checkoutKey??=crypto.randomUUID();const name=(state.profile.full_name||state.profile.name||'').split(' ');return `<section class="page"><p class="eyebrow">${t('checkout.subtitle')}</p><h1>${t('checkout.title')}</h1>${state.data.demo?`<p class="notice">${t('checkout.demo_notice')}</p>`:''}<form data-form="checkout" class="checkout-grid"><div class="form-panel"><h2>${t('checkout.contact')}</h2><div class="field-grid">${field('first_name','checkout.first_name','text',name.shift())}${field('last_name','checkout.last_name','text',name.join(' '))}${field('email','auth.email','email',state.profile.email)}${field('phone','auth.phone','tel',state.profile.phone)}</div><h2>${t('checkout.address')}</h2>${field('line1','checkout.line1')}${field('line2','checkout.line2','text','',false)}<div class="field-grid">${field('city','checkout.city')}${field('county','checkout.county')}${field('postal_code','checkout.postal')}<label class="field">${t('checkout.country')}<select name="country" id="country">${state.data.countries.map(c=>`<option value="${c}">${new Intl.DisplayNames([state.locale],{type:'region'}).of(c)}</option>`).join('')}</select></label></div><p class="fineprint">${t('checkout.billing_same')}</p><h2>${t('checkout.delivery')}</h2><select name="delivery_method" id="delivery" aria-label="${t('checkout.delivery')}"></select><h2>${t('checkout.payment')}</h2><select name="payment_method" id="payment" aria-label="${t('checkout.payment')}">${state.data.payments.map(p=>`<option value="${p.code}">${t(p.label_key)}</option>`).join('')}</select><label class="field">${t('checkout.notes')}<textarea name="notes" maxlength="2000"></textarea></label></div><aside class="order-summary"><h2>${t('checkout.review')}</h2>${bagRows(false)}<div class="totals"><p>${t('bag.subtotal')}<span>${money(state.cart.products_gross_ron)}</span></p><p>${t('bag.shipping')}<span id="shipping-total"></span></p><p class="total">${t('bag.total')}<span id="checkout-total"></span></p></div><label class="check"><input name="accept_terms" type="checkbox" required><span>${t('auth.terms')} ${link('/pages/terms',state.data.pages.find(p=>p.slug==='terms').title)}</span></label>${formError()}<button class="button-primary" type="submit">${icon('buy')}${t(state.data.demo?'checkout.place_demo':'checkout.place')}</button></aside></form></section>`;}
async function updateShipping(){const country=document.querySelector('#country');if(!country)return;state.shippingOptions=await api('/api/checkout/options?country='+country.value);const select=document.querySelector('#delivery');const prev=select.value;select.innerHTML=state.shippingOptions.delivery_methods.map(m=>`<option value="${m.code}" ${m.code===prev?'selected':''}>${t(m.label_key)}</option>`).join('');const method=state.shippingOptions.delivery_methods.find(m=>m.code===select.value);state.shipping=(method.free_over_ron!=null&&state.cart.products_gross_ron>=method.free_over_ron)?0:method.price_ron;document.querySelector('#shipping-total').textContent=money(state.shipping);document.querySelector('#checkout-total').textContent=money(state.cart.products_gross_ron+state.shipping);}
