# Front door al stack-ului cesiro1: SPA /admin/ + proxy catre Flask (backend:4120).
# TLS este terminat de cloudflared, care vorbeste HTTP cu admin:80 -> X-Forwarded-Proto https.

server {
    listen 80;
    server_name _;

    # Redirect-urile nginx (ex. /admin -> /admin/) cu Location RELATIV: altfel nginx construia
    # `http://<host>/admin/` È™i pierdea https (Ã®n spatele cloudflared) È™i portul (local, :4121).
    absolute_redirect off;

    # dist-ul Vite (base: '/admin/') este copiat in /usr/share/nginx/html/admin/
    root /usr/share/nginx/html;

    # upload-uri media prin /api/admin/v1/media
    client_max_body_size 64m;
    # imaginile mari din media_cache trec prin aici
    proxy_read_timeout 120s;

    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_proxied any;
    gzip_comp_level 6;
    gzip_types
        text/plain text/css text/xml
        application/javascript application/json application/xml
        application/rss+xml image/svg+xml font/woff font/woff2;

    # Healthcheck-ul din docker-compose: wget -qO- http://127.0.0.1/healthz
    location = /healthz {
        access_log off;
        add_header Content-Type text/plain;
        return 200 "ok\n";
    }

    # API-urile Flask (inclusiv /admin/api/themes existent in app/factory.py)
    location ^~ /admin/api/ {
        proxy_pass http://backend:4120;
        include /etc/nginx/conf.d/proxy_params.conf;
    }

    location ^~ /api/ {
        proxy_pass http://backend:4120;
        include /etc/nginx/conf.d/proxy_params.conf;
    }

    # Asset-uri cu hash in nume -> cache lung, imutabil
    location ^~ /admin/assets/ {
        access_log off;
        add_header Cache-Control "public, max-age=31536000, immutable";
        try_files $uri =404;
    }

    location = /admin {
        return 301 /admin/;
    }

    # SPA: orice deep-link sub /admin/ (ex. /admin/products/123) cade pe index.html
    location /admin/ {
        add_header Cache-Control "no-cache";
        try_files $uri $uri/ /admin/index.html;
    }

    # Restul: storefront-ul public, /static/, imaginile din media_cache
    location / {
        proxy_pass http://backend:4120;
        include /etc/nginx/conf.d/proxy_params.conf;
    }
}

