const {chromium}=require('./browser/node_modules/playwright');const fs=require('fs');const assert=require('assert');
(async()=>{const b=await chromium.launch();const ctx=await b.newContext({viewport:{width:1440,height:1000}});const p=await ctx.newPage();const base='http://127.0.0.1:4181',inbox='http://127.0.0.1:4182';const logs=[],errors=[];const log=(name,value)=>{logs.push({name,value});console.log(name,JSON.stringify(value))};p.on('pageerror',e=>errors.push(e.message));p.on('response',r=>{if(r.status()>=500)errors.push(r.status()+' '+new URL(r.url()).pathname)});
const api=async(path,data,extra={})=>{const csrf=(await ctx.cookies()).find(c=>c.name==='dracula_csrf')?.value;return ctx.request.fetch(base+path,{method:data===undefined?'GET':'POST',data,headers:{'X-CSRF-Token':csrf||'',...extra}})};
const first=await ctx.request.get(base+'/api/dracula/bootstrap?lang=ro').then(r=>r.json());assert(first.demo);log('brand',{brand:first.brand.name,company:first.legal.company_name,address:first.legal.address,products:first.products.length});
for(const lang of ['ro','en','de']){const d=await ctx.request.get(base+'/api/dracula/bootstrap?lang='+lang).then(r=>r.json());for(const product of d.products){await p.goto(base+'/'+lang+'/product/'+product.external_id);await p.waitForSelector('.dossier-content');const check=await p.locator('.dossier-content').evaluate(el=>({length:el.innerText.length,headings:[...el.querySelectorAll('h2,h3,h4')].map(e=>e.textContent),tables:el.querySelectorAll('table').length,sources:[...el.querySelectorAll('a')].map(a=>a.href),scripts:el.querySelectorAll('script').length}));assert(check.length>1000);assert(check.tables>=1);assert(check.sources.length>=1);assert(!check.scripts);assert.equal(d.products.find(x=>x.id===product.id).image,first.products.find(x=>x.id===product.id).image);log('dossier-'+lang+'-'+product.external_id,check);}}
await p.goto(base+'/en/product/rucsac-business');await p.waitForSelector('.dossier-content');await p.screenshot({path:'outputs/dracula-design-office/audit-dossier-desktop.png',fullPage:true});for(const width of [390,768]){await p.setViewportSize({width,height:844});const v=await p.evaluate(()=>({viewport:innerWidth,width:document.documentElement.scrollWidth,tables:[...document.querySelectorAll('.dossier-content table')].map(x=>({width:x.getBoundingClientRect().width,parent:x.parentElement.getBoundingClientRect().width}))}));assert(v.width<=v.viewport);log('responsive-'+width,v);if(width===390)await p.screenshot({path:'outputs/dracula-design-office/audit-dossier-mobile.png',fullPage:true});}
const email='qa-independent-design-'+Date.now()+'@dracula-design.com';const registered=await api('/api/account/register?lang=en',{email,password:'QAAuditMail121.',full_name:'QA Independent Mail Design',accept_terms:true});assert.equal(registered.status(),201);const user=(await registered.json()).account_id;fs.writeFileSync('work/audit-design-mail-user.json',JSON.stringify({email,id:user}));log('registration',{created:!!user});
const mail=async(match)=>{for(let n=0;n<20;n++){const list=await ctx.request.get(inbox+'/api/v1/messages').then(r=>r.json());for(const m of list.messages){if(match(m))return ctx.request.get(inbox+'/api/v1/message/'+m.ID).then(r=>r.json())}await new Promise(r=>setTimeout(r,1000))}throw Error('Expected local email not captured')};
const verify=await mail(m=>m.To.some(t=>t.Address===email)&&/verify|confirm/i.test(m.Subject));const verifyUrl=verify.Text.match(/http[^\s]+\/en\/account\?verify=[^\s]+/)[0];assert(!/cesiro/i.test(verify.Text+verify.HTML));assert(verify.HTML.includes('Dracula-Company'));assert(verify.HTML.includes('Dracula-Castel'));const verifyResponse=p.waitForResponse(r=>r.url().includes('/api/account/verify-email')&&r.request().method()==='POST');await p.goto(verifyUrl);assert.equal((await verifyResponse).status(),200);await p.waitForSelector('[data-action=logout]');assert(!p.url().includes('verify='));log('verify-email-frontend',{http:200,tokenRemoved:true,brandCorrect:true,from:verify.From.Address,inlineImages:verify.Inline?.length||0});const duplicate=await api('/api/account/verify-email',{token:new URL(verifyUrl).searchParams.get('verify')});log('verification-reuse',duplicate.status());
await api('/api/account/forgot-password?lang=en',{email});const reset=await mail(m=>m.To.some(t=>t.Address===email)&&/password/i.test(m.Subject));assert(!/cesiro/i.test(reset.Text+reset.HTML));const resetUrl=reset.Text.match(/http[^\s]+\/en\/reset-password\?token=[^\s]+/)[0];await p.goto(resetUrl);await p.locator('[name=password]').fill('QAAuditReset121.');await p.locator('[name=password_confirm]').fill('QAAuditReset121.');await p.locator('[data-form=reset] button').click();await p.waitForURL('**/en/account');const login=await api('/api/account/login',{email,password:'QAAuditReset121.'});assert.equal(login.status(),200);log('reset-email-frontend',{reset:true,newPasswordLogin:200,brandCorrect:true});
await p.goto(base+'/en/product/rucsac-business');await p.locator('[data-action=buy]').click();await p.waitForURL('**/checkout');await p.waitForSelector('[name=first_name]');for(const[k,v]of Object.entries({first_name:'QA',last_name:'INDEPENDENT EMAIL DESIGN',phone:'0722123456',line1:'TEST AUDIT - DO NOT SHIP',city:'Brasov',county:'Brasov',postal_code:'500001',notes:'QA DEMO EMAIL AUDIT - NO SHIPMENT NO PAYMENT'}))await p.locator('[name='+k+']').fill(v);await p.locator('[name=accept_terms]').check();const orderResponse=p.waitForResponse(r=>r.url().includes('/api/orders')&&r.request().method()==='POST');await p.locator('form button[type=submit]').click();const response=await orderResponse;assert.equal(response.status(),201);const order=await response.json();assert(order.demo);log('one-demo-order',{number:order.order_number,demo:order.demo});const clientMail=await mail(m=>m.To.some(t=>t.Address===email)&&m.Subject.includes(order.order_number));const adminMail=await mail(m=>!m.To.some(t=>t.Address===email)&&m.Subject.includes(order.order_number));for(const [type,m]of [['client',clientMail],['admin',adminMail]]){assert(!/cesiro/i.test(m.Text+m.HTML));assert(m.HTML.includes('Dracula-Company'));assert(m.HTML.includes('Dracula-Castel'));log('order-email-'+type,{captured:true,subject:m.Subject,brandCorrect:true,inlineImages:m.Inline?.length||0})}
let token=null;p.on('request',r=>{if(r.url().includes('/api/admin/v1/'))token=r.headers().authorization||token});await p.goto(base+'/admin/login?ui=classic');await p.locator('input[type=email]').fill('admin@dracula-design.com');await p.locator('input[type=password]').fill(process.env.QA_PASSWORD);await p.locator('[data-testid=login-submit]').click();await p.waitForTimeout(500);await p.goto(base+'/admin/customers?ui=classic');await p.waitForTimeout(500);const h={'X-Requested-With':'XMLHttpRequest',...(token?{Authorization:token}:{})};const disabled=await ctx.request.post(base+'/api/admin/v1/customers/'+user+'/deactivate',{headers:h,data:{}});assert.equal(disabled.status(),200);log('qa-account-disabled',200);
log('normal-errors',errors);fs.writeFileSync('work/audit-design-dossier-mail-results.json',JSON.stringify(logs,null,2));await b.close();})().catch(e=>{console.error(e.message);process.exit(1)});

